import{_ as e,o,c as d,ao as i}from"./chunks/framework.DagBLaYp.js";const m=JSON.parse('{"title":"Migration to named model workflows","description":"","frontmatter":{},"headers":[],"relativePath":"migration.md","filePath":"migration.md","lastUpdated":null}'),r={name:"migration.md"};function l(s,t,a,n,c,g){return o(),d("div",null,[...t[0]||(t[0]=[i('<h1 id="Migration-to-named-model-workflows" tabindex="-1">Migration to named model workflows <a class="header-anchor" href="#Migration-to-named-model-workflows" aria-label="Permalink to &quot;Migration to named model workflows {#Migration-to-named-model-workflows}&quot;">​</a></h1><p>This redesign intentionally changes the recommended interface:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Earlier workflow</th><th style="text-align:right;">Model workflow</th></tr></thead><tbody><tr><td style="text-align:right;">Kinetic law plus an ordered flat vector</td><td style="text-align:right;"><code>law(name = value, ...)</code> holds the values as fields</td></tr><tr><td style="text-align:right;">Rebuild physical keyword settings in each routine</td><td style="text-align:right;">Reuse <code>CrystallisationModel</code></td></tr><tr><td style="text-align:right;"><code>runsimulation</code> returns problem and solution</td><td style="text-align:right;"><code>solve(CrystallisationProblem(model, conditions, tspan), solver; saveat)</code> returns solution</td></tr><tr><td style="text-align:right;">Separate fixed and free variants</td><td style="text-align:right;">Select a subset in a study specification</td></tr><tr><td style="text-align:right;">Positional PE/MCMC/ABCDE routines</td><td style="text-align:right;"><code>EstimationProblem</code> then <code>solve(problem, alg)</code></td></tr><tr><td style="text-align:right;">Prior arrays indexed by kinetic block order</td><td style="text-align:right;">Named <code>priors</code> of an <code>EstimationProblem</code></td></tr><tr><td style="text-align:right;">First concentration sample treated as C0</td><td style="text-align:right;">Require mapped time-zero observations</td></tr><tr><td style="text-align:right;">Missing likelihood variance gets a fallback</td><td style="text-align:right;">Supplied positive variance or an error loss</td></tr><tr><td style="text-align:right;">Seed mesh rescaled to recover omitted mass</td><td style="text-align:right;">Checked support/domain and no silent rescaling</td></tr><tr><td style="text-align:right;">Anonymous ensemble matrices</td><td style="text-align:right;">Named joint <code>ParameterSamples</code> with sample IDs</td></tr></tbody></table><p>The numerical solver implementations and solution accessors remain reusable. <code>solve(remake(problem; p = values), solver)</code> is the low-level interface for automatic differentiation and sensitivity work. The vector-assembly helpers (<code>prepare_loss</code>, <code>LossSetup</code>, <code>run_ensemble</code>) are internal and no longer exported. Advanced configured solver and SciML interfaces retain their distinct capabilities.</p><h2 id="Removed-positional-routines" tabindex="-1">Removed positional routines <a class="header-anchor" href="#Removed-positional-routines" aria-label="Permalink to &quot;Removed positional routines {#Removed-positional-routines}&quot;">​</a></h2><p>The positional inference, ensemble and plotting routines were deleted. Their replacements are:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Removed</th><th style="text-align:right;">Replacement</th></tr></thead><tbody><tr><td style="text-align:right;"><code>PE_Routine</code>, <code>PE_Routine_Optimisation</code>, <code>MH_minimizer</code></td><td style="text-align:right;"><code>solve(EstimationProblem(model, experiments; bounds), alg)</code>; the minimiser is <code>result.parameters</code></td></tr><tr><td style="text-align:right;"><code>batchLF_procSO</code>, <code>batchLF_procMO</code></td><td style="text-align:right;"><code>loss(estimation_problem, values)</code> and <code>loss_terms(estimation_problem, values)</code></td></tr><tr><td style="text-align:right;"><code>MCMC_Routine</code>, positional <code>nuts_model(experiments, prior, nucl, ...)</code></td><td style="text-align:right;"><code>sample(EstimationProblem(model, experiments; priors), NUTS(), MCMCThreads(), n_samples, n_chains)</code></td></tr><tr><td style="text-align:right;"><code>run_abc</code>, <code>ABCDE_Routine</code>, <code>ABCDE_Turner_Routine</code></td><td style="text-align:right;"><code>sample(EstimationProblem(model, experiments; priors, loss), ABCDE(), n_particles; target)</code>, or <code>ABCDETurner()</code></td></tr><tr><td style="text-align:right;"><code>kinetic_parameter_symbols</code></td><td style="text-align:right;">named paths in <code>result.samples.names</code></td></tr><tr><td style="text-align:right;">positional <code>run_ensemble(distribution or matrix, measurements, nucl, ...)</code>, <code>run_ensemble_fixed</code></td><td style="text-align:right;"><code>predict(result)</code>, <code>predict(result, runs)</code> or <code>predict(model, runs, samples; solver)</code></td></tr><tr><td style="text-align:right;"><code>EnsembleMoMSolution</code>, <code>EnsembleFVSolution</code></td><td style="text-align:right;"><code>PredictionResult</code> holding <code>PredictionEnsemble</code>s; summarise with <code>prediction_summary</code></td></tr><tr><td style="text-align:right;"><code>distribution_to_matrix</code>, <code>prior_to_matrix</code>, <code>create_product_prior</code></td><td style="text-align:right;"><code>parameter_samples(names, distribution)</code> with <code>product_distribution([...])</code></td></tr><tr><td style="text-align:right;"><code>chains_to_matrix</code> (export)</td><td style="text-align:right;"><code>result.samples</code>; the chain stays in <code>result.original</code></td></tr><tr><td style="text-align:right;"><code>plot_measurements_vs_ensemble</code>, <code>plot_ps_measurements_vs_ensemble</code>, <code>plot_measurements_vs_simulation</code>, <code>plot_ps_measurements_vs_simulation</code>, <code>ChainMeasurementPlots</code>, <code>ABCplot</code></td><td style="text-align:right;"><code>plot_predictions(predictions, experiments)</code></td></tr><tr><td style="text-align:right;"><code>ChainPairPlots</code>, DataFrame <code>plot_posterior_pairplot</code> methods</td><td style="text-align:right;"><code>plot_posterior_pairplot(result)</code> or <code>plot_posterior_pairplot(samples; prior, reference)</code></td></tr><tr><td style="text-align:right;"><code>CriSTool.forwardsensitivity(problem, saveat)</code> (SciMLSensitivity <code>ODEForwardSensitivityProblem</code>, MoM and FiniteVol batch only)</td><td style="text-align:right;"><code>ForwardDiff.jacobian(θ -&gt; solve(remake(problem; p = θ), solver; saveat).concentration, θ)</code>, which covers every solver and operation; see <a href="./sensitivity">Sensitivity analysis</a></td></tr><tr><td style="text-align:right;"><code>CRISTOOL_PALETTE</code>, terminal start/end panels, <code>outputdir</code> persistence</td><td style="text-align:right;">removed; plotting functions return a <code>Makie.Figure</code>; save it with <code>save(path, figure)</code></td></tr><tr><td style="text-align:right;"><code>ChainStatsPlots(chain; burnin, title, show_title, saveplot, savestring, savedir, showplot)</code></td><td style="text-align:right;"><code>plot_chain_diagnostics(chain; burnin, title)</code>; an empty <code>title</code> draws none</td></tr><tr><td style="text-align:right;"><code>savename</code>, <code>savedir</code>, <code>showplot</code> keywords of <code>plot_predictions</code> and <code>plot_posterior_pairplot</code></td><td style="text-align:right;">removed; the figure is returned, never saved or displayed: <code>save(path, figure)</code>, <code>display(figure)</code></td></tr></tbody></table><h2 id="Run-conditions,-law-binding-and-study-settings" tabindex="-1">Run conditions, law binding and study settings <a class="header-anchor" href="#Run-conditions,-law-binding-and-study-settings" aria-label="Permalink to &quot;Run conditions, law binding and study settings {#Run-conditions,-law-binding-and-study-settings}&quot;">​</a></h2><p>A second cleanup moved run conditions out of problems and experiments and moved study settings out of <code>fit</code> keywords. The <em>After</em> column shows the current estimation API (see <em>SciML-shaped estimation</em> below).</p><table tabindex="0"><thead><tr><th style="text-align:right;">Before</th><th style="text-align:right;">After</th></tr></thead><tbody><tr><td style="text-align:right;"><code>CrystallisationModel(system = s, nucleation = ..., growth = ...)</code></td><td style="text-align:right;"><code>CrystallisationModel(s; nucleation = ..., growth = ...)</code></td></tr><tr><td style="text-align:right;"><code>KineticModel(nucl_CNT(); parameters = (ln_nucleation_prefactor = 38.0, surface_energy = 6e-4))</code></td><td style="text-align:right;"><code>CNTNucleation(ln_nucleation_prefactor = 38.0, surface_energy = 6e-4)</code></td></tr><tr><td style="text-align:right;"><code>CrystallisationProblem(model; initial_conditions = (concentration = 18.0,), temperature = ConstantTemperature(293.15), initial_crystals = seed, operation = op, solver)</code></td><td style="text-align:right;"><code>CrystallisationProblem(model, RunConditions(temperature = 293.15, concentration = 18.0, crystals = seed, operation = op), tspan)</code>; the solver goes to <code>solve</code></td></tr><tr><td style="text-align:right;"><code>simulate(problem; saveat)</code></td><td style="text-align:right;"><code>solve(problem, solver; saveat)</code></td></tr><tr><td style="text-align:right;"><code>CrystallisationExperiment(...; temperature, initial_from = (concentration = :concentration,), seed_shape, operation, relaxation_initial)</code></td><td style="text-align:right;"><code>CrystallisationExperiment(; observables, exp_id, conditions = RunConditions(...), metadata)</code></td></tr><tr><td style="text-align:right;"><code>initial_from = (crystals = (mass_concentration = :seed_mass, d43 = :d43),)</code> with <code>seed_shape = (family = :lognormal, geometric_std = 1.2)</code></td><td style="text-align:right;"><code>crystals = LogNormalInitialCrystals(mass_concentration = FromObservation(:seed_mass), d43 = FromObservation(:d43), geometric_std = 1.2)</code></td></tr><tr><td style="text-align:right;"><code>relaxation_initial = (...)</code> for steady fits</td><td style="text-align:right;">numeric values in the experiment&#39;s <code>RunConditions</code></td></tr><tr><td style="text-align:right;"><code>load_measurements(path; initial_from, seed_shape, operation, relaxation_initial)</code></td><td style="text-align:right;"><code>load_measurements(path; conditions = (crystals = ..., operation = ...))</code></td></tr><tr><td style="text-align:right;"><code>expt.temperature</code>, <code>expt.initial_crystals</code></td><td style="text-align:right;"><code>expt.conditions.temperature</code>, <code>expt.conditions.crystals</code></td></tr><tr><td style="text-align:right;"><code>fit(prepared; algorithm = DE(...), adtype, searchoptions)</code></td><td style="text-align:right;"><code>solve(EstimationProblem(model, experiments; bounds), DE(...))</code>; an Optimization.jl optimiser takes <code>adtype</code> and its options at <code>solve</code></td></tr><tr><td style="text-align:right;"><code>fit(prepared; sampler = NUTS(), n_samples, n_chains)</code></td><td style="text-align:right;"><code>sample(EstimationProblem(model, experiments; priors), NUTS(), MCMCThreads(), n_samples, n_chains)</code>; requires <code>using Turing</code> (a weak dependency)</td></tr><tr><td style="text-align:right;"><code>fit(prepared; sampler, nparticles, generations, earlystop)</code></td><td style="text-align:right;"><code>sample(problem, ABCDE(), n_particles; target, n_generations, stopping)</code></td></tr><tr><td style="text-align:right;"><code>HPC = true</code></td><td style="text-align:right;"><code>solve(problem, alg; parallel = EnsembleThreads())</code> or <code>sample(problem, sampler, n; parallel = EnsembleThreads())</code></td></tr><tr><td style="text-align:right;"><code>fit(prepared; threaded = true)</code></td><td style="text-align:right;"><code>solve(problem, alg; parallel = EnsembleThreads())</code>; the algorithm picks candidate or experiment threading</td></tr><tr><td style="text-align:right;">ABC target derived by a Wilks test from <code>confidenceinterval</code></td><td style="text-align:right;"><code>sample(problem, ABCDE(), n_particles; target = ...)</code> takes an explicit finite number</td></tr><tr><td style="text-align:right;"><code>parameter_samples(posterior)</code></td><td style="text-align:right;"><code>posterior.samples</code></td></tr><tr><td style="text-align:right;"><code>predict(model, runs, samples)</code> with a default solver</td><td style="text-align:right;"><code>predict(result)</code> or <code>predict(result, runs)</code> reuse the fit&#39;s solver, mode and options; <code>predict(model, runs, samples; solver)</code> requires <code>solver</code></td></tr><tr><td style="text-align:right;"><code>examples/model_helpers.jl</code></td><td style="text-align:right;">removed; the tutorials use the package API directly</td></tr></tbody></table><p>Placeholders are resolved per experiment and the time-zero observations they consume are not scored. Steady fits relax from explicit numeric conditions, so their conditions must not contain placeholders.</p><h2 id="Simulation-modes-and-prepared-losses" tabindex="-1">Simulation modes and prepared losses <a class="header-anchor" href="#Simulation-modes-and-prepared-losses" aria-label="Permalink to &quot;Simulation modes and prepared losses {#Simulation-modes-and-prepared-losses}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Before</th><th style="text-align:right;">After</th></tr></thead><tbody><tr><td style="text-align:right;"><code>prepare_fit(...; mode = :steady, steady_options = SteadyStateOptions(...))</code></td><td style="text-align:right;"><code>EstimationProblem(...; mode = SteadyMode(; relaxation_horizon, reltol, abstol, ...))</code></td></tr><tr><td style="text-align:right;"><code>predict(model, runs, samples; solver, mode = :steady, steady_options)</code></td><td style="text-align:right;"><code>predict(model, runs, samples; solver, mode = SteadyMode(...))</code></td></tr><tr><td style="text-align:right;"><code>mode = :transient</code></td><td style="text-align:right;"><code>mode = TransientMode()</code> (the default)</td></tr><tr><td style="text-align:right;"><code>loss(lf, problem, params, experiments)</code> on a template problem</td><td style="text-align:right;"><code>loss(EstimationProblem(model, experiments; bounds), values)</code></td></tr><tr><td style="text-align:right;"><code>logMLE().string</code>, <code>logMLE().symbols</code>, <code>mae().string</code></td><td style="text-align:right;">removed</td></tr><tr><td style="text-align:right;"><code>logMLE(weighting = [1.0, 1.0])</code> default</td><td style="text-align:right;"><code>weighting = (;)</code>: every observable weighs 1</td></tr><tr><td style="text-align:right;"><code>ensemble.concentration</code> on a <code>PredictionEnsemble</code></td><td style="text-align:right;"><code>observable_values(ensemble, :concentration)</code></td></tr><tr><td style="text-align:right;"><code>prepare_fit(...; initial_time)</code> (always rejected)</td><td style="text-align:right;">not a keyword; runs start at time zero</td></tr></tbody></table><p><code>PredictionEnsemble</code> is no longer an <code>AbstractSolution</code>. Observable weights are resolved once when the loss is prepared and stored with the prepared setup.</p><h2 id="One-solution-type-and-method-based-solvers" tabindex="-1">One solution type and method-based solvers <a class="header-anchor" href="#One-solution-type-and-method-based-solvers" aria-label="Permalink to &quot;One solution type and method-based solvers {#One-solution-type-and-method-based-solvers}&quot;">​</a></h2><p>The four solver-specific result types were merged, and solver configuration flags became values rather than symbols.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Before</th><th style="text-align:right;">After</th></tr></thead><tbody><tr><td style="text-align:right;"><code>CrystallisationMoMSolution</code>, <code>CrystallisationFVSolution</code>, <code>CrystallisationQMOMSolution</code>, <code>CrystallisationDQMOMSolution</code></td><td style="text-align:right;"><code>CrystallisationSolution{Population}</code> with <code>population::MomentPopulation</code>, <code>MeshPopulation</code> or <code>QuadraturePopulation</code>; dispatch on <code>CrystallisationSolution{&lt;:MeshPopulation}</code></td></tr><tr><td style="text-align:right;"><code>solution.numberdensity</code>, <code>solution.voldensity</code>, <code>solution.d50q</code></td><td style="text-align:right;"><code>solution.population.numberdensity</code> (etc.), or <code>state_vars(solution)</code> / <code>size_metrics(solution)</code></td></tr><tr><td style="text-align:right;"><code>solution.moments</code>, <code>solution.nodes</code>, <code>solution.weights</code></td><td style="text-align:right;"><code>solution.population.moments</code> / <code>.nodes</code> / <code>.weights</code>; MoM solutions now also carry <code>moments</code></td></tr><tr><td style="text-align:right;"><code>solution.quadrature_nodes</code>, <code>solution.quadrature_weights</code>, <code>inversion_diagnostics</code>, <code>projection_diagnostics</code></td><td style="text-align:right;"><code>solution.population.nodes</code>, <code>.weights</code>, <code>.diagnostics</code></td></tr><tr><td style="text-align:right;"><code>qmom_quadrature(solution, i)</code>, <code>dqmom_quadrature(solution, i)</code></td><td style="text-align:right;"><code>quadrature(solution, i)</code></td></tr><tr><td style="text-align:right;"><code>getmomentsizes(problem, solution)</code></td><td style="text-align:right;"><code>size_metrics(solution)</code></td></tr><tr><td style="text-align:right;"><code>get_characteristic_size(solution)</code></td><td style="text-align:right;"><code>solution.d43[end]</code> or <code>solution.population.d50q[end]</code></td></tr><tr><td style="text-align:right;"><code>nmoments(::QMOM)</code></td><td style="text-align:right;"><code>moment_order(solver)</code></td></tr><tr><td style="text-align:right;"><code>steady.concentration</code>, <code>steady.d43</code>, <code>steady.time</code>, <code>steady.moments</code></td><td style="text-align:right;"><code>steady.equilibrium.concentration</code> (etc.); <code>steady.solution</code> is the one-sample <code>CrystallisationSolution</code></td></tr><tr><td style="text-align:right;"><code>timestepping_algorithm = :ssprk43</code> (<code>:auto</code>)</td><td style="text-align:right;"><code>timestepping_algorithm = SSPRK43()</code> (<code>nothing</code>)</td></tr><tr><td style="text-align:right;"><code>CriSTool.OrdinaryDiffEq.Euler()</code> and other algorithms through CriSTool&#39;s <code>OrdinaryDiffEq</code> dependency</td><td style="text-align:right;">load the algorithm&#39;s subpackage yourself (for example <code>using OrdinaryDiffEqLowOrderRK: Euler</code>, or <code>using OrdinaryDiffEq</code>); CriSTool depends only on <code>OrdinaryDiffEqTsit5</code> and <code>OrdinaryDiffEqSSPRK</code></td></tr><tr><td style="text-align:right;"><code>tolerance_mode = :auto</code> (<code>:scalar</code>)</td><td style="text-align:right;"><code>auto_abstol = true</code> (<code>false</code>)</td></tr><tr><td style="text-align:right;"><code>QMOM(inversion_algorithm = :wheeler)</code>, solver <code>string</code> fields</td><td style="text-align:right;">removed</td></tr><tr><td style="text-align:right;"><code>runsimulation(params, nucl, gr, agg, br, c0; ...)</code>, <code>runsimulation(params; nucl, gr, ..., initial_crystals)</code></td><td style="text-align:right;"><code>solve(remake(problem; p = params), solver; saveat)</code></td></tr><tr><td style="text-align:right;"><code>DistributionInitialCrystals(...; weighting = :number)</code>, <code>weighting = :volume</code></td><td style="text-align:right;"><code>weighting = NumberWeighted()</code> (default), <code>weighting = VolumeWeighted()</code>; the <code>weighting</code> field holds the singleton</td></tr></tbody></table><p>Every seed description now passes through one resolution. Lognormal and Gaussian seeds become a <code>DistributionInitialCrystals</code>, and mesh solvers receive exact cell integrals of its density whichever entry point built the state (model conditions, experiments, <code>initial_state_from_characteristics</code> or feeds). Previously experiment seeds were point-sampled on the cell centres and rescaled to the target mass.</p><h2 id="Kinetic-laws:-names,-dissolution-slot-and-parameter-schema" tabindex="-1">Kinetic laws: names, dissolution slot and parameter schema <a class="header-anchor" href="#Kinetic-laws:-names,-dissolution-slot-and-parameter-schema" aria-label="Permalink to &quot;Kinetic laws: names, dissolution slot and parameter schema {#Kinetic-laws:-names,-dissolution-slot-and-parameter-schema}&quot;">​</a></h2><p>Kinetic laws and losses now use CamelCase type names. There are no aliases; replace each old name.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Before</th><th style="text-align:right;">After</th></tr></thead><tbody><tr><td style="text-align:right;"><code>nucl_CNT</code></td><td style="text-align:right;"><code>CNTNucleation</code></td></tr><tr><td style="text-align:right;"><code>nucl_CNTnoS</code></td><td style="text-align:right;"><code>CNTNucleationNoSupersaturation</code></td></tr><tr><td style="text-align:right;"><code>nucl_empirical</code></td><td style="text-align:right;"><code>EmpiricalNucleation</code></td></tr><tr><td style="text-align:right;"><code>nucl_empirical_energy</code></td><td style="text-align:right;"><code>ArrheniusNucleation</code></td></tr><tr><td style="text-align:right;"><code>nucl_secondary</code></td><td style="text-align:right;"><code>SecondaryNucleation</code></td></tr><tr><td style="text-align:right;"><code>nucl_prim_plus_second</code>, <code>nucl_CNT_plus_second</code></td><td style="text-align:right;"><code>CombinedNucleation(primary, secondary)</code> for any two nucleation laws; parameters nest under <code>primary</code> and <code>secondary</code></td></tr><tr><td style="text-align:right;"><code>growth_empirical</code></td><td style="text-align:right;"><code>EmpiricalGrowth</code></td></tr><tr><td style="text-align:right;"><code>growth_empirical_length</code></td><td style="text-align:right;"><code>EmpiricalLengthGrowth</code></td></tr><tr><td style="text-align:right;"><code>growth_energy</code>, <code>growth_energy_est</code></td><td style="text-align:right;"><code>ArrheniusGrowth</code>, with <code>activation_energy</code> a parameter between <code>log10_growth_coefficient</code> and <code>growth_order</code></td></tr><tr><td style="text-align:right;"><code>growth_BCF</code></td><td style="text-align:right;"><code>BCFGrowth</code></td></tr><tr><td style="text-align:right;"><code>growth_BpS</code></td><td style="text-align:right;"><code>BirthSpreadGrowth</code></td></tr><tr><td style="text-align:right;"><code>growth_dissolution</code></td><td style="text-align:right;"><code>ArrheniusDissolution</code>, in the <code>dissolution</code> slot</td></tr><tr><td style="text-align:right;"><code>growth_dissolution_length</code></td><td style="text-align:right;"><code>ArrheniusLengthDissolution</code>, in the <code>dissolution</code> slot</td></tr><tr><td style="text-align:right;"><code>growth_energy_dissolution</code></td><td style="text-align:right;"><code>growth = ArrheniusGrowth(...)</code> with <code>activation_energy = 53e3</code>, plus <code>dissolution = ArrheniusDissolution(...)</code></td></tr><tr><td style="text-align:right;"><code>nodissolution</code>, <code>nondissolution</code></td><td style="text-align:right;"><code>NoDissolution</code></td></tr><tr><td style="text-align:right;"><code>noaggregation</code></td><td style="text-align:right;"><code>NoAggregation</code></td></tr><tr><td style="text-align:right;"><code>aggr_scalar</code></td><td style="text-align:right;"><code>ConstantAggregation</code></td></tr><tr><td style="text-align:right;"><code>aggr_linear</code></td><td style="text-align:right;"><code>SizeSumAggregation</code></td></tr><tr><td style="text-align:right;"><code>aggr_linearvol</code></td><td style="text-align:right;"><code>VolumeSumAggregation</code></td></tr><tr><td style="text-align:right;"><code>aggr_avg</code></td><td style="text-align:right;"><code>AverageAggregation</code></td></tr><tr><td style="text-align:right;"><code>nobreakage</code></td><td style="text-align:right;"><code>NoBreakage</code></td></tr><tr><td style="text-align:right;"><code>breakage_empirical</code></td><td style="text-align:right;"><code>EmpiricalBreakage</code></td></tr><tr><td style="text-align:right;"><code>breakage_uniform</code></td><td style="text-align:right;"><code>UniformBreakage</code></td></tr><tr><td style="text-align:right;"><code>logMLE</code></td><td style="text-align:right;"><code>GaussianNLL</code></td></tr><tr><td style="text-align:right;"><code>mae</code></td><td style="text-align:right;"><code>MeanAbsoluteError</code></td></tr><tr><td style="text-align:right;"><code>AbstractFPScalarGrowthFunction</code>, <code>AbstractFPLengthGrowthFunction</code></td><td style="text-align:right;"><code>AbstractScalarGrowthFunction</code>, <code>AbstractLengthGrowthFunction</code></td></tr><tr><td style="text-align:right;"><code>AbstractFPScalarDissolutionFunction</code>, <code>AbstractFPLengthDissolutionFunction</code></td><td style="text-align:right;"><code>AbstractScalarDissolutionFunction</code>, <code>AbstractLengthDissolutionFunction</code></td></tr><tr><td style="text-align:right;"><code>AbstractFPNucleationFunction</code>, <code>AbstractFPGrowthFunction</code></td><td style="text-align:right;"><code>AbstractNucleationFunction</code>, <code>AbstractGrowthFunction</code></td></tr></tbody></table><p>Other changes to kinetic laws:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Before</th><th style="text-align:right;">After</th></tr></thead><tbody><tr><td style="text-align:right;">A dissolution law in the <code>growth</code> slot</td><td style="text-align:right;">Dissolution laws form their own family and go in the <code>dissolution</code> slot; <code>AbstractDissolutionFunction</code> is no longer a subtype of <code>AbstractGrowthFunction</code></td></tr><tr><td style="text-align:right;"><code>nucl_CNT_fixed</code>, <code>nucl_empirical_fixed</code>, <code>growth_empirical_fixed</code></td><td style="text-align:right;">give the ordinary law its values and leave its parameters out of the fit selection; switch nucleation off with <code>NoNucleation()</code> (the <code>CrystallisationModel</code> default)</td></tr><tr><td style="text-align:right;"><code>law.nparams</code>, <code>law.string</code>, <code>law.symbols</code></td><td style="text-align:right;"><code>paramaxis(law)</code> is the only parameter declaration</td></tr><tr><td style="text-align:right;">custom laws without <code>paramaxis</code> (generic <code>θ1, θ2, ...</code> axis)</td><td style="text-align:right;">the default <code>paramaxis</code> names the law&#39;s fields</td></tr><tr><td style="text-align:right;"><code>paramaxis(nucl, gr, agg, br)</code></td><td style="text-align:right;"><code>paramaxis(nucl, gr, diss, agg, br)</code></td></tr><tr><td style="text-align:right;"><code>ConstantSaturation</code>, <code>PolynomialSaturation</code>, <code>CallableSaturation</code>, <code>AbstractSaturationModel</code>, <code>lysozyme_saturation</code></td><td style="text-align:right;">the <code>*Solubility</code> names</td></tr><tr><td style="text-align:right;"><code>net_growthrate</code></td><td style="text-align:right;"><code>net_growth_rate</code></td></tr><tr><td style="text-align:right;"><code>AbstractExperiment</code>, <code>AbstractObservable</code>, <code>AbstractCrystallisationProblem</code>, <code>AbstractDDNucleationFunction</code>, <code>AbstractDDGrowthFunction</code>, <code>AbstractDDScalarGrowthFunction</code></td><td style="text-align:right;">removed</td></tr></tbody></table><h2 id="Configured-problems:-one-source-per-value" tabindex="-1">Configured problems: one source per value <a class="header-anchor" href="#Configured-problems:-one-source-per-value" aria-label="Permalink to &quot;Configured problems: one source per value {#Configured-problems:-one-source-per-value}&quot;">​</a></h2><p><code>CrystallisationProblem</code> now holds the <code>CrystallisationModel</code> and the run conditions instead of copies of their fields, and its only public constructor is <code>CrystallisationProblem(model, conditions, tspan, p; solvent_dynamics, solid_mass_concentration_threshold)</code>; <em>SciML-shaped simulation</em> below lists the latest changes.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Before</th><th style="text-align:right;">After</th></tr></thead><tbody><tr><td style="text-align:right;"><code>CrystallisationProblem(; kinetics_nucleationfunction, parameterset_nucleation, crystal_density, initial_concentration, ...)</code></td><td style="text-align:right;"><code>CrystallisationProblem(model, RunConditions(...), tspan)</code>; give kinetic values in the <code>CrystallisationModel</code> laws</td></tr><tr><td style="text-align:right;"><code>problem.kinetics_growthfunction</code> (and the other four slots)</td><td style="text-align:right;"><code>problem.model.growth</code></td></tr><tr><td style="text-align:right;"><code>problem.parameterset_growth</code> (and the other four slots)</td><td style="text-align:right;"><code>kinetic_parameter_vector(problem).gr</code>, or the fields of <code>problem.model.growth</code></td></tr><tr><td style="text-align:right;"><code>problem.crystal_density</code>, <code>.volume_shape_factor</code>, <code>.molecular_volume</code>, <code>.saturation_model</code>, <code>.material_system</code></td><td style="text-align:right;"><code>problem.model.system.crystal_density</code> (etc.); <code>problem.model.system</code></td></tr><tr><td style="text-align:right;"><code>problem.initial_concentration</code></td><td style="text-align:right;"><code>initial_concentration(problem)</code> (stored once in <code>problem.conditions</code>)</td></tr><tr><td style="text-align:right;"><code>problem.initial_state</code> (full state vector)</td><td style="text-align:right;"><code>initial_state_from_characteristics(problem, solver, seed)</code>; the seed in <code>problem.conditions</code> becomes a solver population at <code>solve</code> time</td></tr><tr><td style="text-align:right;"><code>problem.R_gas_constant</code>, <code>problem.boltzmann_constant</code></td><td style="text-align:right;">module constants <code>CriSTool.CRISTOOL_GAS_CONSTANT</code>, <code>CriSTool.CRISTOOL_BOLTZMANN_CONSTANT</code></td></tr><tr><td style="text-align:right;"><code>crystallisation_odeproblem(solver, problem, saveat)</code> solver method</td><td style="text-align:right;"><code>crystallisation_odeproblem(problem, solver)</code>; <code>problem.p</code> becomes the ODE parameter <code>p</code></td></tr><tr><td style="text-align:right;"><code>system.offset</code> for an entry of <code>CrystallisationSystem(properties = (offset = ...,))</code></td><td style="text-align:right;"><code>system.properties.offset</code> (<code>system_properties(context).offset</code> in callable laws)</td></tr><tr><td style="text-align:right;"><code>context.system</code> in callable laws (<code>KineticContext</code> field)</td><td style="text-align:right;">removed; <code>system_properties(context)</code> for extra properties, <code>context.problem.model.system</code> for the system</td></tr><tr><td style="text-align:right;"><code>CallableNucleation((values, context) -&gt; 0.0; parameters = (;))</code> to switch nucleation off</td><td style="text-align:right;"><code>NoNucleation()</code>, the default <code>nucleation</code> of <code>CrystallisationModel</code>; built in and time invariant, so steady solves need no <code>autonomous = true</code> for it</td></tr><tr><td style="text-align:right;">Unknown <code>CrystallisationProblem</code> keywords copied onto the problem</td><td style="text-align:right;"><code>ArgumentError</code> naming the unsupported settings</td></tr></tbody></table><h2 id="SciML-shaped-simulation" tabindex="-1">SciML-shaped simulation <a class="header-anchor" href="#SciML-shaped-simulation" aria-label="Permalink to &quot;SciML-shaped simulation {#SciML-shaped-simulation}&quot;">​</a></h2><p>Simulation now follows the SciML problem/solve pattern. A <code>CrystallisationProblem</code> no longer stores the solver; it gains a time span and the kinetic values <code>p</code>, and the solver is the second argument of <code>solve</code>, as the algorithm is for an <code>ODEProblem</code>. There are no deprecation shims.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Before</th><th style="text-align:right;">After</th></tr></thead><tbody><tr><td style="text-align:right;"><code>simulate(model, conditions; solver, saveat)</code></td><td style="text-align:right;"><code>solve(CrystallisationProblem(model, conditions, tspan), solver; saveat)</code></td></tr><tr><td style="text-align:right;"><code>CrystallisationProblem(model, conditions; solver)</code></td><td style="text-align:right;"><code>CrystallisationProblem(model, conditions, tspan)</code>; pass the solver to <code>solve(problem, solver)</code></td></tr><tr><td style="text-align:right;"><code>simulate(problem; saveat)</code></td><td style="text-align:right;"><code>solve(problem, solver; saveat)</code>; <code>saveat</code> is a step or a vector of times inside <code>tspan</code></td></tr><tr><td style="text-align:right;"><code>runsimulation(params, problem; save_idx)</code></td><td style="text-align:right;"><code>solve(remake(problem; p = params), solver; saveat)</code></td></tr><tr><td style="text-align:right;"><code>runsimulation(problem; save_idx)</code></td><td style="text-align:right;"><code>solve(problem, solver; saveat)</code></td></tr><tr><td style="text-align:right;"><code>algorithm = Tsit5()</code> on a direct simulation</td><td style="text-align:right;"><code>alg = Tsit5()</code> on <code>solve</code>, <code>EstimationProblem</code> and <code>predict</code></td></tr><tr><td style="text-align:right;"><code>solution.time</code>, <code>ensemble.time</code></td><td style="text-align:right;"><code>solution.t</code>, <code>ensemble.t</code></td></tr><tr><td style="text-align:right;"><code>solution.success</code></td><td style="text-align:right;"><code>solution.retcode</code> (<code>ReturnCode.T</code>) or <code>successful_retcode(solution)</code></td></tr><tr><td style="text-align:right;"><code>observable_values(solution, :d43)</code></td><td style="text-align:right;">also <code>solution[:d43]</code> (any named trajectory)</td></tr><tr><td style="text-align:right;"><code>solve_steadystate(problem; options, initial_guess, algorithm)</code></td><td style="text-align:right;"><code>solve(CrystallisationSteadyStateProblem(problem; u0), solver; alg, relaxation_horizon, reltol, abstol, ...)</code></td></tr><tr><td style="text-align:right;"><code>steady.success</code></td><td style="text-align:right;"><code>steady.retcode</code> (<code>Success</code>, <code>MaxIters</code>, <code>Failure</code> or the ODE code) or <code>successful_retcode(steady)</code>; the ODE code is <code>steady.diagnostics.ode_retcode</code></td></tr><tr><td style="text-align:right;"><code>steady.equilibrium.time</code></td><td style="text-align:right;"><code>steady.equilibrium.t</code></td></tr><tr><td style="text-align:right;"><code>crystallisation_odeproblem(problem, saveat, values)</code></td><td style="text-align:right;"><code>crystallisation_odeproblem(remake(problem; p = values), solver)</code></td></tr><tr><td style="text-align:right;"><code>crystallisation_solution(problem, ode_solution)</code></td><td style="text-align:right;"><code>crystallisation_solution(problem, solver, ode_solution)</code></td></tr><tr><td style="text-align:right;"><code>initial_state_from_characteristics(problem, seed)</code></td><td style="text-align:right;"><code>initial_state_from_characteristics(problem, solver, seed)</code></td></tr><tr><td style="text-align:right;"><code>seed_domain_diagnostics(problem, seed)</code></td><td style="text-align:right;"><code>seed_domain_diagnostics(solver, seed)</code></td></tr><tr><td style="text-align:right;"><code>problem.solver</code>, <code>problem.initial_population</code>, <code>problem.temp_profile</code></td><td style="text-align:right;">the solver is a <code>solve</code> argument; <code>problem.conditions</code> holds temperature, solvent values, seed and operation</td></tr><tr><td style="text-align:right;"><code>rate(law, values, prob::CrystallisationProblem, state, t)</code> in custom laws</td><td style="text-align:right;">leave <code>prob</code> untyped: laws receive the internal solve-time problem, read with <code>supersaturation(prob, state, t)</code>, <code>solvent_state(prob, state)</code> and <code>prob.model</code></td></tr><tr><td style="text-align:right;"><code>CrystallisationProblem(...)</code> throwing on a seed outside the mesh or an unsupported solver/kinetics combination</td><td style="text-align:right;">the same <code>ArgumentError</code> from <code>solve</code></td></tr></tbody></table><h2 id="SciML-shaped-estimation" tabindex="-1">SciML-shaped estimation <a class="header-anchor" href="#SciML-shaped-estimation" aria-label="Permalink to &quot;SciML-shaped estimation {#SciML-shaped-estimation}&quot;">​</a></h2><p>Estimation follows the same problem/solve pattern as simulation. An <code>EstimationProblem</code> replaces the study specifications and <code>prepare_fit</code>; it prepares the solve templates once at construction and subtypes <code>SciMLBase.AbstractSciMLProblem</code>. <code>solve(problem, alg)</code> replaces <code>fit</code> and dispatches on the algorithm. There are no deprecation shims.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Before</th><th style="text-align:right;">After</th></tr></thead><tbody><tr><td style="text-align:right;"><code>prepare_fit(model, experiments, OptimisationSpec(; bounds, algorithm = DE(...)))</code> then <code>fit(prepared)</code></td><td style="text-align:right;"><code>solve(EstimationProblem(model, experiments; bounds), DE(...))</code></td></tr><tr><td style="text-align:right;"><code>OptimisationSpec(; bounds, algorithm = LBFGS(), adtype, searchoptions = (maxiters = 50,))</code></td><td style="text-align:right;"><code>solve(EstimationProblem(model, experiments; bounds), LBFGS(); adtype, maxiters = 50)</code></td></tr><tr><td style="text-align:right;"><code>BayesianSpec(; priors, sampler = NUTS(), n_samples, n_chains)</code></td><td style="text-align:right;"><code>sample(rng, EstimationProblem(model, experiments; priors), NUTS(), MCMCThreads(), n_samples, n_chains; progress)</code>; the <code>rng</code> of <code>fit(prepared; rng, progress)</code> is the first argument</td></tr><tr><td style="text-align:right;"><code>BayesianSpec(; sampler = nothing)</code></td><td style="text-align:right;">pass the sampler explicitly: <code>sample(problem, NUTS(), n_samples)</code></td></tr><tr><td style="text-align:right;"><code>ABCSpec(; priors, target, sampler = ABCDESampler(), n_particles, n_generations, early_stop)</code></td><td style="text-align:right;"><code>sample(EstimationProblem(model, experiments; priors, loss = MeanAbsoluteError()), ABCDE(), n_particles; target, n_generations, stopping)</code></td></tr><tr><td style="text-align:right;"><code>early_stop = true</code> / <code>false</code></td><td style="text-align:right;"><code>stopping = StopAtTarget()</code> / <code>AllGenerations()</code></td></tr><tr><td style="text-align:right;"><code>ABCDETurner(kernel = :gaussian)</code>, <code>:laplace</code>, <code>:none</code></td><td style="text-align:right;"><code>ABCDETurner(kernel = GaussianABCKernel())</code>, <code>LaplaceABCKernel()</code>, <code>FlatABCKernel()</code></td></tr><tr><td style="text-align:right;"><code>ABCSpec</code>&#39;s default <code>loss = MeanAbsoluteError()</code></td><td style="text-align:right;">every <code>EstimationProblem</code> defaults to <code>loss = GaussianNLL()</code>; pass <code>loss = MeanAbsoluteError()</code> for an error discrepancy</td></tr><tr><td style="text-align:right;"><code>ABCDESampler(α)</code>, <code>ABCDETurnerSampler(...)</code></td><td style="text-align:right;"><code>ABCDE(; α)</code>, <code>ABCDETurner(...)</code></td></tr><tr><td style="text-align:right;"><code>prepare_fit(...; solver, mode, problem_options, observable_order, observable_projections, algorithm, solve_options, callback_factory)</code></td><td style="text-align:right;">the same <code>EstimationProblem</code> keywords; the ODE algorithm is <code>alg</code></td></tr><tr><td style="text-align:right;"><code>prepare_fit(...; parallel = EnsembleThreads())</code>, <code>fit(prepared; parallel)</code></td><td style="text-align:right;"><code>solve(problem, alg; parallel = EnsembleThreads())</code></td></tr><tr><td style="text-align:right;"><code>loss(prepared, values)</code>, <code>loss_terms(prepared, values)</code></td><td style="text-align:right;"><code>loss(problem, values)</code>, <code>loss_terms(problem, values)</code></td></tr><tr><td style="text-align:right;"><code>nuts_model(prepared)</code></td><td style="text-align:right;"><code>nuts_model(problem)</code></td></tr><tr><td style="text-align:right;">rebuilding a preparation with another loss or solver</td><td style="text-align:right;"><code>remake(problem; loss, solver, ...)</code></td></tr><tr><td style="text-align:right;"><code>result.preparation</code>, <code>result.preparation.specification</code></td><td style="text-align:right;"><code>result.estimation_problem</code>; the algorithm is <code>result.alg</code></td></tr><tr><td style="text-align:right;"><code>predict(model, runs, samples; solver, algorithm)</code></td><td style="text-align:right;"><code>predict(model, runs, samples; solver, alg)</code></td></tr><tr><td style="text-align:right;"><code>CriSTool.PreparedFit</code></td><td style="text-align:right;"><code>EstimationProblem</code></td></tr></tbody></table><p>A prior-only problem cannot be optimised and a bounds-only problem cannot be sampled; give both, with the same names in the same order, to do both with one problem. Validation that belonged to a sampler specification (a likelihood loss for posterior sampling, positive counts, a finite ABC target) now happens when <code>solve</code> is called, before any sampling.</p><h2 id="Version-1-API" tabindex="-1">Version 1 API <a class="header-anchor" href="#Version-1-API" aria-label="Permalink to &quot;Version 1 API {#Version-1-API}&quot;">​</a></h2><p>Version 1 makes the remaining interfaces follow Julia and SciML conventions. The numerical methods are unchanged. Mesh solves now take a fixed first step (see the table), so their results can differ within the solver tolerances. There are no deprecation shims.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Before</th><th style="text-align:right;">After</th></tr></thead><tbody><tr><td style="text-align:right;"><code>KineticModel(law; parameters = (...))</code>, a law bound to a <code>NamedTuple</code></td><td style="text-align:right;">the law holds its values as fields: <code>EmpiricalGrowth(growth_coefficient = 1e-9, growth_order = 2.0)</code>, like a <code>Distributions.jl</code> distribution; <code>KineticModel</code> is removed</td></tr><tr><td style="text-align:right;"><code>CNTNucleation()</code>, the unbound law</td><td style="text-align:right;">every parameter keyword is required (<code>UndefKeywordError</code> otherwise); a positional call <code>CNTNucleation(38.0, 6e-4)</code> takes the fields in order</td></tr><tr><td style="text-align:right;"><code>model.growth.law</code></td><td style="text-align:right;"><code>model.growth</code></td></tr><tr><td style="text-align:right;"><code>model.growth.parameters.growth_order</code></td><td style="text-align:right;"><code>model.growth.growth_order</code>; a callable law keeps <code>model.growth.parameters</code></td></tr><tr><td style="text-align:right;"><code>EmpiricalLengthGrowth(Lref = 2e-6)</code>, configuration without values</td><td style="text-align:right;"><code>EmpiricalLengthGrowth(growth_coefficient = ..., ..., Lref = 2e-6)</code>; configuration fields keep their defaults and stay out of <code>paramaxis</code></td></tr><tr><td style="text-align:right;">a custom law <code>struct MyGrowth &lt;: AbstractScalarGrowthFunction end</code> plus <code>paramaxis(::MyGrowth)</code> and <code>KineticModel(MyGrowth(); parameters)</code></td><td style="text-align:right;"><code>Base.@kwdef struct MyGrowth{T &lt;: Real} &lt;: AbstractScalarGrowthFunction</code> with one field per parameter; the default <code>paramaxis</code> names the fields</td></tr><tr><td style="text-align:right;"><code>solve(problem, NUTS(); n_samples = 500)</code></td><td style="text-align:right;"><code>sample(problem, NUTS(), 500)</code>, the <code>Turing.sample</code> argument order</td></tr><tr><td style="text-align:right;"><code>solve(problem, NUTS(); n_samples, n_chains = 4, parallel = EnsembleThreads())</code></td><td style="text-align:right;"><code>sample(problem, NUTS(), MCMCThreads(), n_samples, 4)</code>; <code>parallel</code> now only threads the experiments of each chain</td></tr><tr><td style="text-align:right;"><code>solve(problem, NUTS(); rng = MersenneTwister(1))</code></td><td style="text-align:right;"><code>sample(MersenneTwister(1), problem, NUTS(), n)</code></td></tr><tr><td style="text-align:right;"><code>solve(problem, ABCDE(); target, n_particles = 128)</code></td><td style="text-align:right;"><code>sample(problem, ABCDE(), 128; target)</code>; an optional first <code>rng</code> argument now makes ABC draws reproducible</td></tr><tr><td style="text-align:right;"><code>solve(problem, sampler)</code></td><td style="text-align:right;">an <code>ArgumentError</code>: <code>solve</code> runs optimisers only</td></tr><tr><td style="text-align:right;"><code>result.backend_result</code></td><td style="text-align:right;"><code>result.original</code></td></tr><tr><td style="text-align:right;"><code>sum(values(fit.objectives))</code></td><td style="text-align:right;"><code>fit.objective</code></td></tr><tr><td style="text-align:right;">selected values as a vector: <code>last.(…leaves of fit.parameters)</code></td><td style="text-align:right;"><code>fit.u</code></td></tr><tr><td style="text-align:right;">no status on fits and posteriors</td><td style="text-align:right;"><code>fit.retcode</code>, <code>posterior.retcode</code> and <code>successful_retcode(result)</code>; an ABC run whose generations end before every particle reaches <code>target</code> is <code>ReturnCode.MaxIters</code>, and a fit whose optimum failed to simulate is <code>ReturnCode.Failure</code>, whatever the optimiser reports</td></tr><tr><td style="text-align:right;"><code>posterior.objective</code>, <code>posterior.u</code></td><td style="text-align:right;">not defined: a posterior is a set of draws, held in <code>posterior.samples</code></td></tr><tr><td style="text-align:right;"><code>using CriSTool, Metaheuristics</code></td><td style="text-align:right;">still works, but <code>sample</code> is then ambiguous: write <code>using Metaheuristics: DE, Options</code> (or <code>using CriSTool: sample</code>)</td></tr><tr><td style="text-align:right;"><code>CrystallisationSteadyStateProblem(problem; options = SteadyStateOptions(relaxation_horizon = 400.0, autonomous = true))</code></td><td style="text-align:right;"><code>CrystallisationSteadyStateProblem(problem; autonomous = true)</code>, then <code>solve(steady_problem, solver; relaxation_horizon = 400.0)</code>; <code>SteadyStateOptions</code> is removed</td></tr><tr><td style="text-align:right;"><code>SteadyStateOptions(residual_reltol, residual_abstol)</code></td><td style="text-align:right;"><code>solve(steady_problem, solver; reltol, abstol)</code>: steady residual tolerances, as in SciML&#39;s <code>DynamicSS</code></td></tr><tr><td style="text-align:right;"><code>SteadyMode(SteadyStateOptions(...))</code></td><td style="text-align:right;"><code>SteadyMode(; autonomous, relaxation_horizon, reltol, abstol, ...)</code></td></tr><tr><td style="text-align:right;"><code>merge(conditions; concentration = 20.0)</code></td><td style="text-align:right;"><code>remake(conditions; concentration = 20.0)</code></td></tr><tr><td style="text-align:right;">no dense output; <code>sol(t)</code> undefined</td><td style="text-align:right;"><code>solve(problem, solver; dense = true)</code>, then <code>sol(t)</code> (one-point solution) or <code>sol(t, :d43)</code>; without <code>dense = true</code>, <code>sol(t)</code> is an <code>ArgumentError</code></td></tr><tr><td style="text-align:right;"><code>FiniteVol</code> and <code>WENO</code> start from OrdinaryDiffEq&#39;s estimated first step, which falls back to <code>1e-6</code> s with a <code>dt_epsilon</code> warning on sharp or empty meshes</td><td style="text-align:right;">they always start from <code>dt = 1e-6</code> s; <code>solve_options = (; dt = ...)</code> overrides it</td></tr><tr><td style="text-align:right;">a DQMOM node dissolving to <code>minimum_size</code> throws a <code>DomainError</code></td><td style="text-align:right;">the solve stops at the crossing with <code>ReturnCode.Failure</code> and a one-time warning, keeping the trajectory up to it</td></tr><tr><td style="text-align:right;"><code>ensemble.diagnostics[i]</code> as a <code>NamedTuple</code></td><td style="text-align:right;">an <code>EnsembleSampleDiagnostics</code> with the same fields (<code>success</code>, <code>retcode</code>, <code>ode_stats</code>, <code>initial_conditions</code>, <code>convergence</code>, <code>reason</code>); <code>reason</code> is now the failure message as text</td></tr><tr><td style="text-align:right;"><code>rule.diagnostics.status == :deflated</code> (also <code>:ok</code>, <code>:empty</code>)</td><td style="text-align:right;"><code>rule.diagnostics.status == QuadratureStatus.Deflated</code> (<code>QuadratureStatus.OK</code>, <code>.Empty</code>), a scoped enum like <code>ReturnCode</code></td></tr></tbody></table>',36)])])}const p=e(r,[["render",l]]);export{m as __pageData,p as default};
